ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS avatar_url text NOT NULL DEFAULT '';
ALTER TABLE public.postings ADD COLUMN IF NOT EXISTS fund_stage text NOT NULL DEFAULT '';
ALTER TABLE public.postings ADD COLUMN IF NOT EXISTS mba_specific boolean NOT NULL DEFAULT false;
ALTER TABLE public.postings ADD COLUMN IF NOT EXISTS alumni text NOT NULL DEFAULT '';
ALTER TABLE public.postings ADD COLUMN IF NOT EXISTS notes text NOT NULL DEFAULT '';
ALTER TABLE public.postings ADD COLUMN IF NOT EXISTS hidden boolean NOT NULL DEFAULT false;
ALTER TABLE public.postings ADD COLUMN IF NOT EXISTS shared_by_vcc boolean NOT NULL DEFAULT false;
CREATE OR REPLACE FUNCTION public.is_cbs_student() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS (SELECT 1 FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL AND lower(split_part(email,'@',2))='gsb.columbia.edu') $$;
REVOKE ALL ON FUNCTION public.is_cbs_student() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_cbs_student() TO authenticated,service_role;
CREATE TABLE public.student_bookmarks (user_id uuid NOT NULL, job_url text NOT NULL, snapshot jsonb NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'Interested' CHECK(status IN ('Interested','Applied','Interviewing','Offer','Closed')), saved_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,job_url));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.student_bookmarks TO authenticated;
GRANT ALL ON public.student_bookmarks TO service_role;
ALTER TABLE public.student_bookmarks ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_bookmarks ON public.student_bookmarks FOR ALL TO authenticated USING(user_id=auth.uid() AND public.is_cbs_student()) WITH CHECK(user_id=auth.uid() AND public.is_cbs_student());
CREATE TABLE public.student_preferences (user_id uuid PRIMARY KEY, filters jsonb NOT NULL DEFAULT '{}', digest_enabled boolean NOT NULL DEFAULT false, resume_account boolean NOT NULL DEFAULT false);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.student_preferences TO authenticated;
GRANT ALL ON public.student_preferences TO service_role;
ALTER TABLE public.student_preferences ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_preferences ON public.student_preferences FOR ALL TO authenticated USING(user_id=auth.uid() AND public.is_cbs_student()) WITH CHECK(user_id=auth.uid() AND public.is_cbs_student());
CREATE TABLE public.broken_link_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, posting_id uuid NOT NULL, reported_at timestamptz NOT NULL DEFAULT now(), resolved boolean NOT NULL DEFAULT false, UNIQUE(user_id,posting_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.broken_link_reports TO authenticated;
GRANT ALL ON public.broken_link_reports TO service_role;
ALTER TABLE public.broken_link_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY students_report ON public.broken_link_reports FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.is_cbs_student());
CREATE POLICY reports_read ON public.broken_link_reports FOR SELECT TO authenticated USING(public.is_cbs_student() AND (user_id=auth.uid() OR public.has_role(auth.uid(),'admin')));
CREATE POLICY admins_resolve ON public.broken_link_reports FOR UPDATE TO authenticated USING(public.is_cbs_student() AND public.has_role(auth.uid(),'admin')) WITH CHECK(public.is_cbs_student() AND public.has_role(auth.uid(),'admin'));
REVOKE ALL ON public.postings,public.sources,public.scrape_runs FROM anon;
DROP POLICY IF EXISTS postings_public_read ON public.postings;
DROP POLICY IF EXISTS "signed-in read postings" ON public.postings;
CREATE POLICY students_read_postings ON public.postings FOR SELECT TO authenticated USING(public.is_cbs_student() AND (NOT hidden OR public.has_role(auth.uid(),'admin')));
CREATE POLICY student_posting_boundary ON public.postings AS RESTRICTIVE FOR ALL TO authenticated USING(public.is_cbs_student()) WITH CHECK(public.is_cbs_student());
DROP POLICY IF EXISTS sources_public_read ON public.sources;
DROP POLICY IF EXISTS scrape_runs_public_read ON public.scrape_runs;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.sources TO authenticated;
GRANT SELECT ON public.scrape_runs TO authenticated;
CREATE POLICY admins_sources ON public.sources FOR ALL TO authenticated USING(public.is_cbs_student() AND public.has_role(auth.uid(),'admin')) WITH CHECK(public.is_cbs_student() AND public.has_role(auth.uid(),'admin'));
CREATE POLICY admins_runs ON public.scrape_runs FOR SELECT TO authenticated USING(public.is_cbs_student() AND public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.board_last_verified() RETURNS timestamptz LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT max(ended_at) FROM public.scrape_runs WHERE public.is_cbs_student() AND status IN ('success','partial') AND sources_succeeded>0 $$;
REVOKE ALL ON FUNCTION public.board_last_verified() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.board_last_verified() TO authenticated;
CREATE POLICY student_profile_boundary ON public.profiles AS RESTRICTIVE FOR ALL TO authenticated USING(public.is_cbs_student()) WITH CHECK(public.is_cbs_student());
CREATE POLICY student_resume_boundary ON public.resumes AS RESTRICTIVE FOR ALL TO authenticated USING(public.is_cbs_student()) WITH CHECK(public.is_cbs_student());
CREATE POLICY student_analyses_boundary ON public.job_analyses AS RESTRICTIVE FOR ALL TO authenticated USING(public.is_cbs_student()) WITH CHECK(public.is_cbs_student());
CREATE POLICY student_roles_boundary ON public.user_roles AS RESTRICTIVE FOR ALL TO authenticated USING(public.is_cbs_student()) WITH CHECK(public.is_cbs_student());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.profiles,public.resumes,public.job_analyses TO authenticated;
GRANT SELECT ON public.user_roles TO authenticated;
CREATE OR REPLACE FUNCTION public.cbs_auth_lifecycle() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF lower(split_part(NEW.email,'@',2)) <> 'gsb.columbia.edu' OR NEW.email IS NULL THEN RAISE EXCEPTION 'A Columbia Business School email is required'; END IF;
 INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,left(coalesce(NEW.raw_user_meta_data->>'display_name',split_part(NEW.email,'@',1)),100)) ON CONFLICT(id) DO NOTHING;
 IF NEW.email_confirmed_at IS NOT NULL AND lower(NEW.email)='joyoun27@gsb.columbia.edu' THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'admin') ON CONFLICT(user_id,role) DO NOTHING; END IF;
 RETURN NEW; END $$;
CREATE TRIGGER cbs_student_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.cbs_auth_lifecycle();
CREATE TRIGGER cbs_student_verified AFTER UPDATE OF email,email_confirmed_at ON auth.users FOR EACH ROW EXECUTE FUNCTION public.cbs_auth_lifecycle();
CREATE OR REPLACE FUNCTION public.grant_student_admin(target_email text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE target uuid; BEGIN
 IF NOT public.is_cbs_student() OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF;
 SELECT id INTO target FROM auth.users WHERE lower(email)=lower(trim(target_email)) AND email_confirmed_at IS NOT NULL AND last_sign_in_at IS NOT NULL AND lower(split_part(email,'@',2))='gsb.columbia.edu';
 IF target IS NULL THEN RAISE EXCEPTION 'Student must sign in with their verified CBS email first'; END IF;
 INSERT INTO public.user_roles(user_id,role) VALUES(target,'admin') ON CONFLICT(user_id,role) DO NOTHING;
 END $$;
REVOKE ALL ON FUNCTION public.grant_student_admin(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.grant_student_admin(text) TO authenticated;
ALTER TABLE public.postings ADD CONSTRAINT posting_stage_values CHECK (fund_stage IN ('','pre-seed','seed','Series A','growth','multi-stage'));